-- Name: _slugify(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._slugify(text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  select trim(both '-' from regexp_replace(lower($1), '[^a-z0-9]+', '-', 'g'))
$_$;


ALTER FUNCTION public._slugify(text) OWNER TO postgres;

